'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const root=path.resolve(__dirname,'../..'),html=fs.readFileSync(path.join(root,'index.html'),'utf8');
const a=html.indexOf('/* Stage63: ability NAME-only preflight and controlled draft.'),b=html.indexOf('let pcInsanePreviewSheets=null',a);assert.ok(a>0&&b>a);const source=html.slice(a,b);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x])),pcRuleCurrentData=p=>p.ruleSheets?.insane||{resources:[]};
const api=new Function('escapeHTML','pcRuleCurrentData',source+'\nreturn {check:pcInsaneAbilityPreflight,html:pcInsaneAbilityPreflightHTML};')(escapeHTML,pcRuleCurrentData);
const pc=()=>({ruleMeta:{systemId:'insane',editionId:'2013-original',confirmed:true},ruleSheets:{insane:{resources:[]}}}),row=(name,ref,state='changed')=>({ref,value:name,state}),sample=(...rows)=>({comparison:true,groups:{abilities:rows}});
test('Round210 reads only changed non-formula ability names from source H17-H37',()=>{const r=api.check(sample(row('虚构能力','H18'),row('原预置','H19','unchanged'),row('=formula','H20','formula'),row('最后一格','H37')),pc());assert.equal(r.length,3);assert.deepEqual(r.filter(x=>x.status==='名称来源已核对').map(x=>x.ref),['H18','H37']);assert.equal(r[1].status,'待核对');});
test('Round210 rejects duplicate, existing PC name, invalid refs and unconfirmed edition',()=>{const p=pc();p.ruleSheets.insane.resources.push({label:'已有能力',value:'手填',future:{keep:true}});const r=api.check(sample(row('重复','H18'),row('重复','H19'),row('已有能力','H20'),row('越界','P40')),p);assert.equal(r[0].status,'待核对');assert.equal(r[1].status,'待核对');assert.equal(r[2].status,'已有同名能力');assert.equal(r[3].status,'待核对');p.ruleMeta.confirmed=false;assert.equal(api.check(sample(row('新能力','H21')),p)[0].status,'待核对');});
test('Round210 missing comparison or other rules returns no assumptions',()=>{assert.deepEqual(api.check(sample(row('新能力','H21')),{ruleMeta:{systemId:'coc'},ruleSheets:{insane:{resources:[]}}}),[]);assert.deepEqual(api.check({comparison:false,groups:{abilities:[row('新能力','H21')]}},pc()),[]);});
test('Round210 privacy and HTML escape remain source-limited',()=>{const out=api.html(api.check(sample(row('<svg onload=alert(1)>','H21')),pc()));assert.match(out,/&lt;svg/);assert.doesNotMatch(out,/<svg onload/);assert.doesNotMatch(source,/saveState\s*\(|pcDraft\s*=|pcWorkbookPut\s*\(|P40|effects\b/);assert.match(html,/pcInsaneAbilityPreflightHTML\(pcInsaneAbilityPreflight\(supplement,pcDraft\)\)/);});
test('Round210 installed in both CI workflows and version consistent',()=>{for(const n of ['pl-browser-synthetic.yml','pl-native-restore-gate.yml'])assert.match(fs.readFileSync(path.join(root,'.github/workflows',n),'utf8'),/round210-insane-ability-name-preflight\.test\.cjs/);assert.match(html,/const APP_UI_VERSION = "8\.1\.12\.\d+"/);});
